-- Hosbah (MH-576 D8): the edge cache toggle for an app — an agent-managed Varnish container in
-- front of the app's own upstream on its server (internal/agent/cache.go), one row per app. Caddy's
-- official binary (a plain release tarball, see caddy.install) has no cache module, and Varnish needs
-- no per-deploy reconfiguration: it always dials a loopback-only Caddy server that mirrors the app's
-- live upstream, so a release's ephemeral port never desyncs it. status tracks the agent's last
-- cache.set result (off|pending|running|error); hits/misses/last_purged_at are refreshed opportunis-
-- tically from varnishstat whenever cache.set or cache.purge runs — not a live counter.
ALTER TABLE app_edge_caches ADD CONSTRAINT app_edge_caches_app_id_key UNIQUE (app_id);
CREATE INDEX app_edge_caches_team_idx ON app_edge_caches (team_id);
